LAYER
  NAME "c_rezago_educativo_sexo_edad_alfa_hombres"
  STATUS ON
  TYPE POLYGON
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, alfa_hombres FROM rezago_educativo_censo_2020.rez_educ_edad_sexo_2020_alfa WHERE the_geom && !BOX!) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Hombres en condición de analfabetismo"
    "wms_enable_request" "*"
  END
  CLASS
    NAME "bajo"
    EXPRESSION ([alfa_hombres] <=370.25)
    STYLE
      OUTLINECOLOR 0 128 0
      WIDTH 0.8
      OPACITY 60
      COLOR 0 128 0
    END
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
  CLASS
    NAME "medio"
    EXPRESSION ([alfa_hombres] >370.25 and [alfa_hombres] <=716.0)
    STYLE
      OUTLINECOLOR 255 255 0
      WIDTH 0.8
      OPACITY 60
      COLOR 255 255 0
    END
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
  CLASS
    NAME "alto"
    EXPRESSION ([alfa_hombres] >716.0 and [alfa_hombres] <=1304.25)
    STYLE
      OUTLINECOLOR 240 120 15
      WIDTH 0.8
      OPACITY 60
      COLOR 240 120 15
    END
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
  CLASS
    NAME "muy_alto"
    EXPRESSION ([alfa_hombres] >1304.25)
    STYLE
      OUTLINECOLOR 255 0 0
      WIDTH 0.8
      OPACITY 60
      COLOR 255 0 0
    END
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
END

